/// host dispatches this with the full {@link SessionInputRequest} to append a new
/// entry to {@link SessionState.inputNeeded} or replace the existing entry with
/// the same `id`.
///
/// Server-originated: the host mirrors chat-level requests (elicitations, tool
/// confirmations, client-tool executions) into the session aggregate so clients
/// subscribed only to the session channel can discover them. Clients respond by
/// dispatching the ordinary `chat/*` action to the entry's `chat` channel — see
/// {@link SessionInputRequest}.</summary>
public sealed record SessionInputNeededSetAction
{
    public ActionType Type { get; init; }

    /// <summary>The input request to add or update, matched by `id`.</summary>
    public required SessionInputRequest Request { get; init; }
}

/// <summary>A session-level input request was removed.
///
/// Removes the entry identified by `id` from
/// {@link SessionState.inputNeeded}; a no-op when no entry matches.
///
/// Server-originated: the host dispatches this once the underlying request
/// resolves (the user answers, the tool call is confirmed, or the client
/// reports its result).</summary>
public sealed record SessionInputNeededRemovedAction
{
    public ActionType Type { get; init; }

    /// <summary>The `id` of the input request to remove.</summary>
    public required string Id { get; init; }
}

/// <summary>The session's customizations have changed.
///
/// Full-replacement semantics: the `customizations` array replaces the
/// previous `customizations` entirely.</summary>
public sealed record SessionCustomizationsChangedAction
{
    public ActionType Type { get; init; }

    /// <summary>Updated customization list (full replacement).</summary>
    public required List<Customization> Customizations { get; init; }
}

/// <summary>A client updated a customization's enablement decisions.
///
/// Matches `id` against every top-level customization first — a plugin or
/// directory container, or a bare top-level MCP server — then against the
/// children inside each container (a skill, agent, or other entry). Plugins
/// and MCP servers retain the matched entry's explicit decisions; other
/// entries update their `enabled` flag. Disabling a plugin still disables all
/// of its children — the effective state of a plugin child is the plugin's
/// derived enabled value and `(child.enabled ?? true)` — so toggling a child
/// only matters while its plugin is enabled. Is a no-op when no
/// customization has the given `id`.
///
/// The `enablement` array completely replaces all explicit decisions. A caller
/// changing one scope must include every decision it intends to preserve.</summary>
public sealed record SessionCustomizationToggledAction
{
    public ActionType Type { get; init; }

    /// <summary>The id of the container or child to update.</summary>
    public required string Id { get; init; }

    /// <summary>Explicit enablement decisions, replacing the previous list entirely.</summary>
    public required List<CustomizationEnablement> Enablement { get; init; }
}

/// <summary>Upserts a top-level customization (plugin or directory).
///
/// The reducer locates the existing entry by `customization.id`:
///
/// - If found, the entry is replaced entirely with `customization`,
///   including its `children` array. To preserve existing children, the
///   host must include them on the payload.
/// - If not found, the entry is appended.</summary>
public sealed record SessionCustomizationUpdatedAction
{
    public ActionType Type { get; init; }

    /// <summary>The customization to upsert (matched by `customization.id`).</summary>
    public required Customization Customization { get; init; }
}

/// <summary>Removes a customization by id.
///
/// Searches every container and its children for the entry. If the entry
/// is a container, its children are removed with it. Is a no-op when no
/// matching id is found.</summary>
public sealed record SessionCustomizationRemovedAction
{
    public ActionType Type { get; init; }

    /// <summary>The id of the customization to remove.</summary>
    public required string Id { get; init; }
}

/// <summary>Updates the runtime fields of an existing
/// {@link McpServerCustomization} — narrow alternative to
/// {@link SessionCustomizationUpdatedAction} for the high-frequency
/// `starting` ↔ `ready` ↔ `authRequired` transitions.
///
/// Locates the target entry by `id`, searching both the top-level
/// customization list and the `children` array of every container.
/// Replaces the entry's {@link McpServerCustomization.state | `state`}
/// and {@link McpServerCustomization.channel | `channel`}
/// (full-replacement semantics: omit `channel` to clear an existing
/// channel URI). Other fields of the customization are preserved.
///
/// Is a no-op when no matching `McpServerCustomization` is found. To
/// update any other field (name, icons, `mcpApp` capabilities, etc.) use
/// {@link SessionCustomizationUpdatedAction} instead.
///
/// When the transition is to {@link McpServerStatus.AuthRequired}
/// because of a request issued mid-turn, the host SHOULD also raise
/// {@link SessionStatus.InputNeeded} on the session — see
/// {@link McpServerAuthRequiredState} for the rationale.</summary>
public sealed record SessionMcpServerStateChangedAction
{
    public ActionType Type { get; init; }

    /// <summary>The id of the {@link McpServerCustomization} to update.</summary>
    public required string Id { get; init; }

    /// <summary>The new lifecycle state.</summary>
    public required McpServerState State { get; init; }

    /// <summary>Updated `mcp://` side-channel URI. Full-replacement: omit to clear
    /// an existing channel (typical when leaving
    /// {@link McpServerStatus.Ready | `Ready`}).</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Channel { get; init; }
}

/// <summary>Requests that the host start or restart an existing
/// {@link McpServerCustomization}.
///
/// Locates the target entry by `id`, searching both the top-level
/// customization list and the `children` array of every container. The
/// reducer optimistically moves the server to
/// {@link McpServerStatus.Starting | `starting`} and clears any previous
/// {@link McpServerCustomization.channel | `channel`}; the host remains
/// authoritative and SHOULD follow with
/// {@link SessionMcpServerStateChangedAction | `session/mcpServerStateChanged`}
/// once the server becomes ready, needs authentication, fails, or is
/// rejected. Is a no-op when no matching `McpServerCustomization` is found.</summary>
public sealed record SessionMcpServerStartRequestedAction
{
    public ActionType Type { get; init; }

    /// <summary>The id of the {@link McpServerCustomization} to start.</summary>
    public required string Id { get; init; }
}

/// <summary>Requests that the host stop an existing {@link McpServerCustomization}.
///
/// Locates the target entry by `id`, searching both the top-level
/// customization list and the `children` array of every container. The
/// reducer optimistically moves the server to
/// {@link McpServerStatus.Stopped | `stopped`} and clears any previous
/// {@link McpServerCustomization.channel | `channel`}. Replacing an
/// {@link McpServerStatus.AuthRequired | `authRequired`} lifecycle state with
/// `stopped` unblocks the server from waiting on authentication. If the host
/// also raised session-level input-needed state solely for that MCP server, it
/// SHOULD remove that input-needed entry when accepting the stop.
///
/// The host remains authoritative and MAY reject the action or follow with
/// {@link SessionMcpServerStateChangedAction | `session/mcpServerStateChanged`}
/// if the final lifecycle state differs. Is a no-op when no matching
/// `McpServerCustomization` is found.</summary>
public sealed record SessionMcpServerStopRequestedAction
{
    public ActionType Type { get; init; }

    /// <summary>The id of the {@link McpServerCustomization} to stop.</summary>
    public required string Id { get; init; }
}

/// <summary>Truncates a session's history. If `turnId` is provided, all turns after that
/// turn are removed and the specified turn is kept. If `turnId` is omitted, all
/// turns are removed.
///
/// If there is an active turn it is silently dropped and the session status
/// returns to `idle`.
///
/// Common use-case: truncate old data then dispatch a new
/// `session/turnStarted` with an edited message.</summary>
public sealed record SessionTruncatedAction
{
    public ActionType Type { get; init; }

    /// <summary>Keep turns up to and including this turn. Omit to clear all turns.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? TurnId { get; init; }
}

/// <summary>Client changed a mutable config value mid-session.
///
/// Only properties with `sessionMutable: true` in the config schema may be
/// changed. The server validates and broadcasts the action; the reducer merges
/// the new values into `state.config.values`.</summary>
public sealed record SessionConfigChangedAction
{
    public ActionType Type { get; init; }

    /// <summary>Updated config values</summary>
    public required Dictionary<string, JsonElement> Config { get; init; }

    /// <summary>When `true`, replaces all config values instead of merging</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public bool? Replace { get; init; }
}

/// <summary>The session's `_meta` side-channel changed. Replaces `state._meta`
/// entirely (full-replacement semantics). Producers SHOULD merge any
/// keys they wish to preserve into the new value before dispatching.</summary>
public sealed record SessionMetaChangedAction
{
    public ActionType Type { get; init; }

    /// <summary>New `_meta` payload, or `undefined` to clear it</summary>
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; init; }
}

/// <summary>Partial content produced while a tool is still executing.
///
/// Replaces the `content` array on the running tool call state. Clients can
/// use this to display live feedback (e.g. a terminal reference) before the
/// tool completes.
///
/// For client-provided tools (where `toolClientId` is set on the tool call state),
/// the owning client dispatches this action to stream intermediate content while
/// executing. The server SHOULD reject this action if the dispatching client does
/// not match `toolClientId`.</summary>
public sealed record SessionToolCallContentChangedAction
{
    /// <summary>Turn identifier</summary>
    public required string TurnId { get; init; }

    /// <summary>Tool call identifier</summary>
    public required string ToolCallId { get; init; }

    /// <summary>Additional provider-specific metadata for this tool call.
    ///
    /// Clients MAY look for well-known keys here to provide enhanced UI.
    /// For example, a `ptyTerminal` key with `{ input: string; output: string }`
    /// indicates the tool operated on a terminal (both `input` and `output` may
    /// contain escape sequences).</summary>
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; init; }

    public ActionType Type { get; init; }

    /// <summary>The current partial content for the running tool call</summary>
    public required List<ToolResultContent> Content { get; init; }
}

/// <summary>A chat was added to this session's catalog. Upsert semantics: if a chat
/// with the same `summary.resource` already exists, the existing entry is
/// replaced.
///
/// Mirrors the root-channel `root/sessionAdded` notification.</summary>
public sealed record SessionChatAddedAction
{
    public ActionType Type { get; init; }

    /// <summary>The full summary of the newly added (or upserted) chat.</summary>
    public required ChatSummary Summary { get; init; }
}

/// <summary>A chat was removed from this session's catalog. No-op when no entry matches.
///
/// Mirrors the root-channel `root/sessionRemoved` notification.</summary>
public sealed record SessionChatRemovedAction
{
    public ActionType Type { get; init; }

    /// <summary>The URI of the chat to remove.</summary>
    public required string Chat { get; init; }
}

/// <summary>One existing chat's summary fields changed.
///
/// Partial-update semantics: only fields present in `changes` are written;
/// omitted fields are preserved. Identity fields (`resource`) MUST NOT be
/// carried in `changes`. No-op when no entry with `chat` exists — clients
/// SHOULD then wait for a {@link SessionChatAddedAction | `session/chatAdded`}.
///
/// Mirrors the root-channel `root/sessionSummaryChanged` notification.</summary>
public sealed record SessionChatUpdatedAction
{
    public ActionType Type { get; init; }

    /// <summary>The URI of the chat whose summary changed.</summary>
    public required string Chat { get; init; }

    /// <summary>Mutable summary fields that changed; omitted fields are unchanged.
    ///
    /// Identity fields (`resource`) never change and MUST be omitted by
    /// senders; receivers SHOULD ignore them if present.</summary>
    public required PartialChatSummary Changes { get; init; }
}

/// <summary>The default chat input-routing hint for this session changed.</summary>
public sealed record SessionDefaultChatChangedAction
{
    public ActionType Type { get; init; }

    /// <summary>New default chat URI, or `undefined` to clear the hint.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? DefaultChat { get; init; }
}

/// <summary>A new message has been sent to the agent, and a new turn starts.
///
/// A client is only allowed to send {@link MessageKind.User} messages.</summary>
public sealed record ChatTurnStartedAction
{
    public ActionType Type { get; init; }

    /// <summary>Turn identifier</summary>
    public required string TurnId { get; init; }

    /// <summary>ISO 8601 timestamp when this turn started.</summary>
    public required string StartedAt { get; init; }

    /// <summary>The new message</summary>
    public required Message Message { get; init; }

    /// <summary>If this turn was auto-started from a queued message, the ID of that message</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? QueuedMessageId { get; init; }

    /// <summary>Additional provider-specific metadata for this action.
    ///
    /// Clients MAY look for well-known keys here to provide enhanced UI, and
    /// agent hosts MAY use it to carry per-event context that does not fit any
    /// other field — for example, attributing the event to a specific agent
    /// (such as a sub-agent acting within the turn). Mirrors the MCP `_meta`
    /// convention.</summary>
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; init; }
}

/// <summary>Streaming text chunk from the assistant, appended to a specific response part.
///
/// The server MUST first emit a `chat/responsePart` to create the target
/// markdown part, then use this action to append text to it.</summary>
public sealed record ChatDeltaAction
{
    public ActionType Type { get; init; }

    /// <summary>Turn identifier</summary>
    public required string TurnId { get; init; }

    /// <summary>Identifier of the response part to append to</summary>
    public required string PartId { get; init; }

    /// <summary>Text chunk</summary>
    public required string Content { get; init; }

    /// <summary>Additional provider-specific metadata for this action.
    ///
    /// Clients MAY look for well-known keys here to provide enhanced UI, and
    /// agent hosts MAY use it to carry per-event context that does not fit any
    /// other field — for example, attributing the event to a specific agent
    /// (such as a sub-agent acting within the turn). Mirrors the MCP `_meta`
    /// convention.</summary>
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; init; }
}

/// <summary>Structured content appended to the response.
///
/// An {@link ErrorResponsePart} MUST be appended with {@link ChatErrorAction}
/// instead so adding the part and ending the turn are one atomic transition.</summary>
public sealed record ChatResponsePartAction
{
    public ActionType Type { get; init; }

    /// <summary>Turn identifier</summary>
