    /// <summary>Additional provider-specific metadata for this action.
    ///
    /// Clients MAY look for well-known keys here to provide enhanced UI, and
    /// agent hosts MAY use it to carry per-event context that does not fit any
    /// other field — for example, attributing the event to a specific agent
    /// (such as a sub-agent acting within the turn). Mirrors the MCP `_meta`
    /// convention.</summary>
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; init; }
}

/// <summary>A tool call begins — parameters are streaming from the LM.
///
/// The server sets {@link ToolCallContributor | `contributor`} to identify
/// the origin of the tool. For client-provided tools, the named client is
/// responsible for executing the tool once it reaches the `running` state
/// and dispatching `chat/toolCallComplete`. For MCP-served tools, the
/// server executes the call against the named `McpServerCustomization`.</summary>
public sealed record ChatToolCallStartAction
{
    /// <summary>Turn identifier</summary>
    public required string TurnId { get; init; }

    /// <summary>Tool call identifier</summary>
    public required string ToolCallId { get; init; }

    /// <summary>Additional provider-specific metadata for this tool call.
    ///
    /// Clients MAY look for well-known keys here to provide enhanced UI.
    /// For example, a `ptyTerminal` key with `{ input: string; output: string }`
    /// indicates the tool operated on a terminal (both `input` and `output` may
    /// contain escape sequences).</summary>
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; init; }

    public ActionType Type { get; init; }

    /// <summary>Internal tool name (for debugging/logging)</summary>
    public required string ToolName { get; init; }

    /// <summary>Human-readable tool name</summary>
    public required string DisplayName { get; init; }

    /// <summary>Human-readable description of what the tool invocation intends to do</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Intention { get; init; }

    /// <summary>Reference to the contributor of the tool being called. Absent for
    /// server-side tools that are not contributed by a client or MCP server.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ToolCallContributor? Contributor { get; init; }
}

/// <summary>Streaming partial parameters for a tool call.</summary>
public sealed record ChatToolCallDeltaAction
{
    /// <summary>Turn identifier</summary>
    public required string TurnId { get; init; }

    /// <summary>Tool call identifier</summary>
    public required string ToolCallId { get; init; }

    /// <summary>Additional provider-specific metadata for this tool call.
    ///
    /// Clients MAY look for well-known keys here to provide enhanced UI.
    /// For example, a `ptyTerminal` key with `{ input: string; output: string }`
    /// indicates the tool operated on a terminal (both `input` and `output` may
    /// contain escape sequences).</summary>
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; init; }

    public ActionType Type { get; init; }

    /// <summary>Partial parameter content to append, if provided by the host.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Content { get; init; }

    /// <summary>Updated progress message</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public StringOrMarkdown? InvocationMessage { get; init; }
}

/// <summary>Tool call parameters are complete, or a running tool requires re-confirmation.
///
/// When dispatched for a `streaming` tool call, transitions to `pending-confirmation`
/// or directly to `running` if `confirmed` is set.
///
/// When dispatched for a `running` tool call (e.g. mid-execution permission needed),
/// transitions back to `pending-confirmation`. The `invocationMessage` and `_meta`
/// SHOULD be updated to describe the specific confirmation needed. Clients use the
/// standard `chat/toolCallConfirmed` flow to approve or deny.
///
/// For client-provided tools, the server typically sets `confirmed` to
/// `'not-needed'` so the tool transitions directly to `running`, where the
/// owning client can begin execution immediately.</summary>
public sealed record ChatToolCallReadyAction
{
    /// <summary>Turn identifier</summary>
    public required string TurnId { get; init; }

    /// <summary>Tool call identifier</summary>
    public required string ToolCallId { get; init; }

    /// <summary>Additional provider-specific metadata for this tool call.
    ///
    /// Clients MAY look for well-known keys here to provide enhanced UI.
    /// For example, a `ptyTerminal` key with `{ input: string; output: string }`
    /// indicates the tool operated on a terminal (both `input` and `output` may
    /// contain escape sequences).</summary>
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; init; }

    public ActionType Type { get; init; }

    /// <summary>Final contributor metadata. MUST NOT change execution ownership established
    /// at `chat/toolCallStart`; a client contributor must keep the same `clientId`.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ToolCallContributor? Contributor { get; init; }

    /// <summary>Final human-readable description of what the tool invocation intends to do.
    /// When present, replaces the provisional intention from `chat/toolCallStart`.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Intention { get; init; }

    /// <summary>Message describing what the tool will do or what confirmation is needed</summary>
    public required StringOrMarkdown InvocationMessage { get; init; }

    /// <summary>Final tool input</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ToolInput? ToolInput { get; init; }

    /// <summary>Short title for the confirmation prompt (e.g. `"Run in terminal"`, `"Write file"`)</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public StringOrMarkdown? ConfirmationTitle { get; init; }

    /// <summary>Risk assessment that informed the confirmation requirement.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ToolCallRiskAssessment? RiskAssessment { get; init; }

    /// <summary>File edits that this tool call will perform, for preview before confirmation</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public JsonElement? Edits { get; init; }

    /// <summary>Whether the agent host allows the client to edit the tool's input parameters before confirming</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public bool? Editable { get; init; }

    /// <summary>If set, the tool was auto-confirmed and transitions directly to `running`</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ToolCallConfirmationReason? Confirmed { get; init; }

    /// <summary>Options the server offers for this confirmation. When present, the client
    /// SHOULD render these instead of a plain approve/deny UI. Each option
    /// belongs to a {@link ConfirmationOptionGroup} so the client can still
    /// categorise the choices.</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public List<ConfirmationOption>? Options { get; init; }
}

/// <summary>
/// ChatToolCallConfirmedAction — the client approves or denies a
/// pending chat tool call (merged approved + denied variants on the wire).
/// </summary>
public sealed record ChatToolCallConfirmedAction
{
    public ActionType Type { get; init; }

    public required string TurnId { get; init; }

    public required string ToolCallId { get; init; }

    // _meta is snake_case; camelCase(Meta) would be "meta".
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; init; }

    public bool Approved { get; init; }

    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ToolCallConfirmationReason? Confirmed { get; init; }

    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ToolCallCancellationReason? Reason { get; init; }

    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? EditedToolInput { get; init; }

    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Message? UserSuggestion { get; init; }

    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public StringOrMarkdown? ReasonMessage { get; init; }

    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? SelectedOptionId { get; init; }
}

/// <summary>Tool execution finished. Transitions to `completed` or `pending-result-confirmation`
/// if `requiresResultConfirmation` is `true`.
///
/// For client-provided tools (whose tool call state carries a client
/// `ToolCallContributor` with a `clientId`), the owning client dispatches this
/// action with the execution result. The server SHOULD reject this action if the
/// dispatching client does not match the contributor's `clientId`.
///
/// Servers waiting on a client tool call MAY time out after a reasonable duration
/// if the implementing client disconnects or becomes unresponsive, and dispatch
/// this action with `result.success = false` and an appropriate error.
///
/// A client MAY also dispatch this action with a **failed** result (
/// `result.success: false`) for a tool call currently in `auth-required`
/// status, to cancel that invocation without completing the pending MCP
/// authentication challenge. This always transitions the tool call straight
/// to `completed`, preserving the fields it had before pausing for auth;
/// `requiresResultConfirmation` is ignored for this transition; the
/// cancellation can never enter `pending-result-confirmation`, since there is
/// no real result to review.
///
/// A **successful** result (`result.success: true`) is invalid for a tool
/// call in `auth-required` status — execution never resumed after the
/// challenge, so there's nothing that could have produced it. The reducer
/// MUST reject/ignore it as a no-op, leaving the tool call in
/// `auth-required`. The client must resolve the auth challenge
/// (`chat/toolCallAuthResolved`) before completing successfully.</summary>
public sealed record ChatToolCallCompleteAction
{
    /// <summary>Turn identifier</summary>
    public required string TurnId { get; init; }

    /// <summary>Tool call identifier</summary>
    public required string ToolCallId { get; init; }

    /// <summary>Additional provider-specific metadata for this tool call.
    ///
    /// Clients MAY look for well-known keys here to provide enhanced UI.
    /// For example, a `ptyTerminal` key with `{ input: string; output: string }`
    /// indicates the tool operated on a terminal (both `input` and `output` may
    /// contain escape sequences).</summary>
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; init; }

    public ActionType Type { get; init; }

    /// <summary>Execution result</summary>
    public required ToolCallResult Result { get; init; }

    /// <summary>If true, the result requires client approval before finalizing</summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public bool? RequiresResultConfirmation { get; init; }
}

/// <summary>Client approves or denies a tool's result.
///
/// If `approved` is `false`, the tool transitions to `cancelled` with reason `result-denied`.</summary>
public sealed record ChatToolCallResultConfirmedAction
{
    /// <summary>Turn identifier</summary>
    public required string TurnId { get; init; }

    /// <summary>Tool call identifier</summary>
    public required string ToolCallId { get; init; }

    /// <summary>Additional provider-specific metadata for this tool call.
    ///
    /// Clients MAY look for well-known keys here to provide enhanced UI.
    /// For example, a `ptyTerminal` key with `{ input: string; output: string }`
    /// indicates the tool operated on a terminal (both `input` and `output` may
    /// contain escape sequences).</summary>
    [JsonPropertyName("_meta")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, JsonElement>? Meta { get; init; }

    public ActionType Type { get; init; }

    /// <summary>Whether the result was approved</summary>
    public bool Approved { get; init; }
}

/// <summary>Partial content produced while a tool is still executing.
///
/// Replaces the `content` array on the running tool call state. Clients can
